/**
 * Name and level lookups for save data (Gen III and IV), backed by src/data/save-tables.json
 * (generated by `npm run generate-save-tables`).
 */
import tablesJson from "../../data/save-tables.json";
import type { Gender, SaveMon } from "./types";

interface SaveTables {
  moves: string[];
  abilities: string[];
  items4: Record<string, string>;
  locations4: Record<string, string>;
  /** species id → growth rate id */
  growth: number[];
  /** growth rate id → total EXP needed for each level (index = level) */
  exp: Record<string, number[]>;
  /** English species names by National Dex number */
  species: string[];
  /** Eighths of the species that are female; -1 = genderless */
  genderRate: number[];
  /** Gen III internal species index → National Dex number */
  species3: Record<string, number>;
  items3: Record<string, string>;
  locations3: Record<string, string>;
  /** species → regular abilities that exist in Gen III, in slot order */
  abilities3: number[][];
}

const tables = tablesJson as unknown as SaveTables;

export function moveName(id: number): string {
  return tables.moves[id] || `Move #${id}`;
}

export function abilityName(id: number): string {
  return tables.abilities[id] || `Ability #${id}`;
}

/** Item and met-location numbers mean different things in Gen III and Gen IV. */
export function itemName(index: number, gen: 3 | 4 = 4): string {
  return (gen === 3 ? tables.items3 : tables.items4)[index] ?? `Item #${index}`;
}

export function locationName(index: number, gen: 3 | 4 = 4): string {
  if (gen === 3) {
    if (index === 254) return "In-game trade";
    if (index === 255) return "Fateful encounter";
    return tables.locations3[index] ?? `Location #${index}`;
  }
  return tables.locations4[index] ?? `Location #${index}`;
}

export const heldItemName = (mon: Pick<SaveMon, "heldItem" | "gen">): string => itemName(mon.heldItem, mon.gen ?? 4);
export const metLocationName = (mon: Pick<SaveMon, "metLocation" | "gen">): string => locationName(mon.metLocation, mon.gen ?? 4);

export function speciesName(species: number): string {
  return tables.species[species] || `#${species}`;
}

/** National Dex number for a Gen III internal species index (undefined for the unused 252–276 and anything unknown). */
export function nationalFromGen3(index: number): number | undefined {
  return tables.species3[index];
}

/** English names of the species' abilities in Gen III, in slot order. */
export function abilityNames3(species: number): string[] {
  return (tables.abilities3[species] ?? []).map(abilityName);
}

/** Gen III stores only which ability slot a Pokémon has; a species with one ability uses it for both. */
export function abilityForSlot3(species: number, slot: number): number {
  const options = tables.abilities3[species] ?? [];
  return options[slot] ?? options[0] ?? 0;
}

/** Gen III has no gender field: it follows from the low byte of the PID and the species' gender ratio. */
export function genderFromPid(species: number, pid: number): Gender {
  const rate = tables.genderRate[species] ?? 0;
  if (rate < 0) return "genderless";
  if (rate === 0) return "male";
  if (rate >= 8) return "female";
  return (pid & 0xff) < rate * 32 - 1 ? "female" : "male";
}

// The ball byte uses item indices for the 16 standard balls; HeartGold/SoulSilver's
// Apricorn balls continue at 17 but sit at item index 492 onwards.
const FIRST_APRICORN_BALL = 17;
const FIRST_APRICORN_ITEM = 492;

export function ballName(ball: number): string {
  if (ball === 0) return "Poké Ball";
  return itemName(ball >= FIRST_APRICORN_BALL ? FIRST_APRICORN_ITEM + ball - FIRST_APRICORN_BALL : ball);
}

/** Boxed Pokémon don't store their level — it follows from EXP and the species' growth curve. */
export function levelFromExp(species: number, exp: number): number {
  const curve = tables.exp[tables.growth[species]];
  if (!curve) return 1;
  let level = 1;
  while (level < 100 && exp >= curve[level + 1]) level++;
  return level;
}

const ORIGIN_GAMES: Record<number, string> = {
  1: "Sapphire",
  2: "Ruby",
  3: "Emerald",
  4: "FireRed",
  5: "LeafGreen",
  7: "HeartGold",
  8: "SoulSilver",
  10: "Diamond",
  11: "Pearl",
  12: "Platinum",
  15: "Colosseum/XD",
};

export function originGameName(code: number): string {
  return ORIGIN_GAMES[code] ?? `Game #${code}`;
}
